sys_module.content:
var AssetLookupUtils = Class.create();
AssetLookupUtils.prototype = {
    initialize: function () {},

    getAssetsForUser: function (userId) {
        if (gs.getCurrentScopeName() !== 'global') {
            return null;
        }

        var assets = [];
        var gr = new GlideRecord('alm_hardware');
        gr.addQuery('assigned_to', userId);
        gr.setLimit(100);
        gr.query();
        while (gr.next()) {
            assets.push({
                display_name: gr.getValue('display_name'),
                install_status: gr.getValue('install_status')
            });
        }
        return assets;
    },

    type: 'AssetLookupUtils'
};
